-- pintopets_allergies: tenant-scoped rows behind /allergies (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_allergies (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            allergen VARCHAR(255) NOT NULL,
            reaction VARCHAR(255),
            severity VARCHAR(255) NOT NULL,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_allergies_severity_check CHECK (severity IN ('mild', 'moderate', 'severe'))
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_allergies_namespace ON pintopets_allergies (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_allergies_pet ON pintopets_allergies (namespace_id, pet_uuid)")
end
